<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('users.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['_action']??'save'; if($action==='save'){ $id=(int)($_POST['id']??0); $data=[(int)$_POST['branch_id'],(int)($_POST['staff_id']??0)?:null,(int)$_POST['role_id'],trim($_POST['username']),$_POST['status']]; if(!$id){$hash=password_hash($_POST['password'],PASSWORD_DEFAULT); q('INSERT INTO users(branch_id,staff_id,role_id,username,password_hash,status,created_at) VALUES(?,?,?,?,?,?,NOW())',[$data[0],$data[1],$data[2],$data[3],$hash,$data[4]]); audit('create','users',(int)db()->lastInsertId());} else {q('UPDATE users SET branch_id=?,staff_id=?,role_id=?,username=?,status=? WHERE id=?',array_merge($data,[$id])); if(!empty($_POST['password'])) q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($_POST['password'],PASSWORD_DEFAULT),$id]); audit('update','users',$id);} flash('success','User saved.'); redirect('modules/users.php');}
 if($action==='role_perm'){ $role=(int)$_POST['role_id']; q('DELETE FROM role_permissions WHERE role_id=?',[$role]); foreach($_POST['perm']??[] as $pid) q('INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)',[$role,(int)$pid]); flash('success','Role permissions saved.'); redirect('modules/users.php?role='.$role);} }
$edit=null;if(isset($_GET['edit']))$edit=one('SELECT * FROM users WHERE id=?',[(int)$_GET['edit']]); $rows=all('SELECT u.*,r.name role,s.full_name staff,b.name branch FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN staff s ON s.id=u.staff_id JOIN branches b ON b.id=u.branch_id ORDER BY u.id DESC'); $roles=all('SELECT * FROM roles ORDER BY name'); $branches=all('SELECT * FROM branches ORDER BY name'); $title='Users & Roles'; $subtitle='Role-based access control for owner, manager, receptionist, cashier, inventory, staff and custom users.'; include dirname(__DIR__).'/includes/header.php';?><div class="toolbar"><a class="btn" href="?new=1">+ Add User</a></div><?php if(isset($_GET['new'])||$edit):?><section class="card"><h2><?= $edit?'Edit':'Add' ?> User</h2><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><div class="form-group"><label>Branch</label><select name="branch_id"><?php foreach($branches as $b):?><option value="<?=e($b['id'])?>"<?=selected($edit['branch_id']??$bid,$b['id'])?>><?=e($b['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Staff</label><select name="staff_id"><option value="">No staff link</option><?php foreach(all('SELECT id,full_name FROM staff ORDER BY full_name') as $s):?><option value="<?=e($s['id'])?>"<?=selected($edit['staff_id']??'',$s['id'])?>><?=e($s['full_name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Role</label><select name="role_id"><?php foreach($roles as $r):?><option value="<?=e($r['id'])?>"<?=selected($edit['role_id']??'',$r['id'])?>><?=e($r['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Username</label><input name="username" required value="<?=e($edit['username']??'')?>"></div><div class="form-group"><label>Password <?= $edit?'(blank to keep)':'' ?></label><input type="password" name="password" <?= $edit?'':'required minlength="8"' ?>></div><div class="form-group"><label>Status</label><select name="status"><option value="active"<?=selected($edit['status']??'active','active')?>>Active</option><option value="inactive"<?=selected($edit['status']??'','inactive')?>>Inactive</option><option value="locked"<?=selected($edit['status']??'','locked')?>>Locked</option></select></div></div><button class="btn">Save User</button></form></section><?php endif;?><div class="grid cols-2"><section class="card"><h2>Users</h2><table><thead><tr><th>User</th><th>Staff</th><th>Role</th><th>Branch</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['staff'])?></td><td><?=e($r['role'])?></td><td><?=e($r['branch'])?></td><td><?=e($r['status'])?></td><td><a class="btn small light" href="?edit=<?=e($r['id'])?>">Edit</a></td></tr><?php endforeach;?></tbody></table></section><section class="card"><h2>Role Permissions</h2><form method="get" class="toolbar"><select name="role" data-autosubmit><?php $roleId=(int)($_GET['role']??1); foreach($roles as $r):?><option value="<?=e($r['id'])?>"<?=selected($roleId,$r['id'])?>><?=e($r['name'])?></option><?php endforeach;?></select></form><?php $perms=all('SELECT * FROM permissions ORDER BY module,code'); $assigned=q('SELECT permission_id FROM role_permissions WHERE role_id=?',[$roleId])->fetchAll(PDO::FETCH_COLUMN);?><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="role_perm"><input type="hidden" name="role_id" value="<?=e($roleId)?>"><div class="grid cols-2"><?php foreach($perms as $p):?><label><input type="checkbox" name="perm[]" value="<?=e($p['id'])?>"<?=checked(in_array($p['id'],$assigned))?>> <?=e($p['module'])?> — <?=e($p['name'])?></label><?php endforeach;?></div><button class="btn" style="margin-top:12px">Save Permissions</button></form></section></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>